147	        if (then == null || !(then.isOpen() || then == ClaimStatus.SETTLED)) {
148	            return false;
149	        }
150	        boolean deferred = then == ClaimStatus.OPEN && claim.getDeferredUntil() != null && claim.getDeferredUntil().isAfter(today);
151	        return !deferred && !(claim.getStatus().isOpen() && !claim.isBound() && leftOn(claim, person, today));
152	    }
153	
154	    /** Whether the claim, while OPEN or PENDING and unbound, leaves the live totals on the day: its person's
155	     *  retirement date is reached (null person: not retired). A hold, the claim's or its person's, does not take it
156	     *  out; it only denies its person a pool cut. */
157	    private static boolean leftOn(Claim claim, Person person, LocalDate today) {
158	        return person != null && person.retiredBy(today);
159	    }
160	
161	    /** The percent of the grade's rate in force on a date; none when that rate's to-date is before it. When the
162	     *  sheet has none in force then, the next sheet up its chain's (the rates of each sheet come in chain order). */
163	    private Optional<BigDecimal> rateOn(String grade, LocalDate on) {
164	        return rateOn(grade, on, rates);
165	    }
166	
167	    /** The percent of the grade's rate that applies to the claim on its date, as {@link #rateOn(String, LocalDate)}:
168	     *  a forward-only rate saved after the claim was added does not apply to it ({@link Rate#forClaim}). */
169	    private Optional<BigDecimal> rateOn(String grade, Claim claim) {
170	        return rateOn(grade, claim.getDate(), rates.stream().flatMap(r -> r.forClaim(claim.getId()).stream()).toList());
171	    }
172	
173	    private static Optional<BigDecimal> rateOn(String grade, LocalDate on, List<Rate> rates) {
174	        List<String> chain = new ArrayList<>();
175	        rates.stream().map(Rate::getSheetId).filter(id -> !chain.contains(id)).forEach(chain::add);
176	        for (String sheetId : chain) {
177	            Optional<BigDecimal> pct = rates.stream()
178	                    .filter(r -> r.getSheetId().equals(sheetId) && r.getGrade().equals(grade))
179	                    .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(on))
180	                    .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
181	                    .filter(r -> !r.endedBy(on))
