185	            }
186	        }
187	        return Optional.empty();
188	    }
189	
190	    /** The due the claim would have today as an open claim bound by no statement: its live figure at today's rates,
191	     *  grades and floor, plus the late charge it would carry on that as an open claim; null when it has none (n/a). */
192	    public BigDecimal openDue(Claim claim) {
193	        BigDecimal figure = liveFigure(claim);
194	        if (figure == null) {
195	            return null;
196	        }
197	        if (claim.isCorrection() || claim.isWaived() || !lateFrom(claim).isBefore(today)) {
198	            return floored(claim, figure);
199	        }
200	        BigDecimal floored = floored(claim, figure);
201	        return floored.add(chargeByBoundary(claim, floored));
202	    }
