204	    /** The claim's due: its frozen due when settled, else the due its person's last statement bound it to, else the
205	     *  greater of its floor and its figure, plus the late charge worked out on that; null when it has none (n/a). */
206	    public BigDecimal due(Claim claim) {
207	        if (claim.getDue() != null) {
208	            return claim.getDue();
209	        }
210	        if (claim.isBound()) {
211	            return claim.getStatedDue();
212	        }
213	        BigDecimal figure = figure(claim);
214	        if (figure == null) {
215	            return null;
216	        }
217	        BigDecimal floored = floored(claim, figure);
218	        return floored.add(lateCharge(claim, floored));
219	    }
