221	    /** The claim's figure, without any late charge or floor (a bound claim's: the due it is bound to); null when it
222	     *  has none (n/a). */
223	    public BigDecimal figure(Claim claim) {
224	        if (claim.getDue() != null) {
225	            return claim.getDue();
226	        }
227	        if (claim.isBound()) {
228	            return claim.getStatedDue();
229	        }
230	        return liveFigure(claim);
231	    }
232	
233	    /** The claim's live figure: neither frozen nor bound; null when it has none (n/a). */
234	    private BigDecimal liveFigure(Claim claim) {
235	        return rateOn(grades.on(claim.getDate()), claim)
236	                .map(pct -> rateFigure(claim.getAmount(), pct, rounding(claim)))
237	                .orElse(null);
238	    }
239	
240	    /** The claim's due less its holders' parts (each its due times their share divided by 100, rounded half to
241	     *  even): what its own person's due-total counts of it; null when it has none (n/a). */
242	    public BigDecimal ownDue(Claim claim) {
243	        BigDecimal due = due(claim);
244	        return due == null ? null : due.subtract(ClaimShares.parts(claim, due));
245	    }
