254	    /** The person's live due-total, as {@link #dueTotal(List, LocalDate)}; their OPEN claims do not count once their
255	     *  retirement date is reached, unless a statement binds them. At most the sheet's cap (n/a is not capped). */
256	    public String dueTotal(List<Claim> claims, LocalDate today, Person person) {
257	        return dueTotal(claims, today, person, null);
258	    }
259	
260	    /** The person's live due-total, as {@link #dueTotal(List, LocalDate, Person)}, with their parts of the claims of
261	     *  others shared with them (null: they hold no share of a counted claim) added before the cap: their own claims
262	     *  count less the holders' parts, and when they would have none (n/a) their parts are their due-total. */
263	    public String dueTotal(List<Claim> claims, LocalDate today, Person person, BigDecimal held) {
264	        return dueTotal(claims, today, person, held, null);
265	    }
266	
267	    /** The person's live due-total, as {@link #dueTotal(List, LocalDate, Person, BigDecimal)}, with the cap covering
268	     *  it plus their cut total (null: none): it is held to the cap less their cut total, not below 0.00. */
269	    public String dueTotal(List<Claim> claims, LocalDate today, Person person, BigDecimal held, BigDecimal cut) {
270	        String sum = uncappedDueTotal(claims, today, person);
271	        if (held != null) {
272	            sum = ("n/a".equals(sum) ? held : new BigDecimal(sum).add(held)).setScale(2).toPlainString();
273	        }
274	        if (cap == null || "n/a".equals(sum)) {
275	            return sum;
276	        }
277	        BigDecimal limit = cut == null ? cap : cap.subtract(cut).max(BigDecimal.ZERO);
278	        if (new BigDecimal(sum).compareTo(limit) <= 0) {
279	            return sum;
280	        }
281	        return limit.setScale(2).toPlainString();
282	    }
283	
284	    /** The person's live due-total before the cap: the sum of their figures. */
285	    private String uncappedDueTotal(List<Claim> claims, LocalDate today, Person person) {
286	        List<Claim> counted = claims.stream().filter(c -> countsLive(c, person, today)).toList();
287	        String grade = grades.on(today);
288	        boolean kept = counted.stream().anyMatch(c -> c.getDue() != null || (c.isBound() && c.getStatedDue() != null)
289	                || (!c.isBound() && (!grade.equals(grades.on(c.getDate())) || !c.getDate().isAfter(today)) && figure(c) != null));
290	        if (rateOn(grade, today).isEmpty() && !kept) {
291	            return "n/a";
292	        }
293	        return counted.stream().map(this::ownDue).filter(f -> f != null)
