package net.officefloor.hq.app.plan;

import java.time.LocalDate;
import java.util.List;

/** A plan as the screen shows it: its person, amount (two decimals), start, every N days or day of the month (the other
 *  null), end, how many claims it has made so far, its next dates: the first five plan dates after the sheet's today
 *  and on or before its end that no pause skips (while paused, none until it is resumed), whether it is paused, and its amount
 *  changes, oldest first, each as <date> amount=<amount>, and the descendant sheet its claims are generated on (null for this sheet). */
public record PlanResponse(Long id, Long personId, String amount, String start, Integer every, Integer day, String end,
        long generated, List<String> nextDates, boolean paused, List<String> changes, String sheet) {

    public static PlanResponse of(Plan plan, LocalDate today, PlanClaimRepository made, PlanPauseRepository pauses,
            PlanChangeRepository changes) {
        List<PlanPause> taken = pauses.findByPlanIdOrderByIdAsc(plan.getId());
        return new PlanResponse(plan.getId(), plan.getPersonId(), plan.getAmount().setScale(2).toPlainString(),
                plan.getStart().toString(), plan.getEvery(), plan.getDay(),
                plan.getEnd().toString(), made.countByPlanId(plan.getId()),
                plan.nextDatesAfter(today, 5, d -> taken.stream().anyMatch(p -> p.skips(d))).stream()
                        .map(LocalDate::toString).toList(),
                taken.stream().anyMatch(PlanPause::isOpen),
                changes.findByPlanIdOrderByIdAsc(plan.getId()).stream()
                        .map(c -> c.getChangedOn() + " amount=" + c.getAmount().setScale(2).toPlainString()).toList(),
                plan.getTargetSheetId());
    }
}
        this.every = every;
        this.day = day;
        this.end = end;
        this.targetSheetId = targetSheetId;
    }

    /** The plan's dates, up to its end and the given day: the start then every N days, or for a monthly plan its day
     *  in every month from the start's month (a day beyond the month's length on its last day), those before the start
     *  left out. */
    public List<LocalDate> datesUpTo(LocalDate today) {
        LocalDate last = today != null && today.isBefore(end) ? today : end;
        List<LocalDate> dates = new ArrayList<>();
        if (day != null) {
            for (YearMonth m = YearMonth.from(start); !m.atDay(1).isAfter(last); m = m.plusMonths(1)) {
                LocalDate d = m.atDay(Math.min(day, m.lengthOfMonth()));
                if (!d.isBefore(start) && !d.isAfter(last)) {
                    dates.add(d);
                }
            }
            return dates;
        }
        for (LocalDate d = start; !d.isAfter(last); d = d.plusDays(every)) {
            dates.add(d);
        }
        return dates;
    }

    /** The plan's next dates: the first given number of its dates after the given day and on or before its end, those
     *  skipped left out. */
    public List<LocalDate> nextDatesAfter(LocalDate today, int limit, Predicate<LocalDate> skipped) {
        return datesUpTo(null).stream().filter(d -> today == null || d.isAfter(today)).filter(skipped.negate())
                .limit(limit).toList();
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public LocalDate getStart() {
        return start;
    }

    public Integer getEvery() {
        return every;
    }

    public Integer getDay() {
        return day;
    }

    public LocalDate getEnd() {
        return end;
    }

    public String getTargetSheetId() {
        return targetSheetId;
    }
}
-- A plan's pauses: paused on a day (the sheet's today) and resumed on a later one (null while it is still paused).
-- A plan date on or after the day it was paused and before the day it was resumed is skipped, not postponed.
CREATE TABLE plan_pause (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    plan_id BIGINT NOT NULL REFERENCES plan (id),
    paused_on DATE NOT NULL,
    resumed_on DATE
);
CREATE INDEX plan_pause_plan ON plan_pause (plan_id, id);

